1	import type {
2	  HookCallback,
3	  HookJSONOutput,
4	  Options,
5	  PermissionResult,
6	  Query,
7	  SDKMessage,
8	  SDKUserMessage,
9	} from '@anthropic-ai/claude-agent-sdk'
10	import type { CodeSession, PermissionDecision, SessionEvent } from '../session/code-session'
11	import type { SessionHooks } from '../session/hooks'
12	import type { ModelProfile } from '../session/model-profile'
13	import { AsyncQueue } from '../session/async-queue'
14	import { SdkEventMapper } from './sdk-event-mapper'
15	import { spawnWithRuntime, type NodeRuntime } from './node-runtime'
16	import { bareToolName, toolServer } from './tool-server'
17	import { ReadTracker } from '../openai-session/tools/read-tracker'
18	import type { Tool } from '../openai-session/tools/tool'
19	
20	type QueryFn = (params: { prompt: AsyncIterable<SDKUserMessage>; options?: Options }) => Query
21	
22	export type SdkSessionOptions = {
23	  id: string
24	  profile: ModelProfile
25	  cwd: string
26	  /** Absolute path to the SDK's cli.js. */
27	  cliPath: string
28	  runtime: NodeRuntime
29	  /** Engine session id from an earlier `session_started`, to continue that conversation. */
30	  resumeEngineSessionId?: string
31	  /** Extra environment for the engine process, on top of the host's. */
32	  env?: Record<string, string>
33	  hooks?: SessionHooks
34	  /** Replaces Claude Code's own system prompt; phases use this. */
35	  systemPrompt?: string
36	  /** Restricts the built-in tools to these names. */
37	  tools?: string[]
38	  /** Tools this extension owns, served to the engine in-process on top of the built-ins. */
39	  ownTools?: Tool[]
40	  query: QueryFn
41	  onStderr?: (chunk: string) => void
42	  /** Receives one line per engine message, for diagnosing what the engine does and does not send. */
43	  trace?: (line: string) => void
44	}
45	
46	type PendingPermission = {
47	  resolve: (result: PermissionResult) => void
48	  input: Record<string, unknown>
49	}
50	
51	/**
52	 * Claude through the Agent SDK. One `query()` in streaming-input mode per
53	 * session, so one engine process serves every turn of the conversation.
54	 */
55	export class SdkSession implements CodeSession {
56	  readonly id: string
57	  readonly profile: ModelProfile
58	  private readonly input = new AsyncQueue<SDKUserMessage>()
59	  private readonly output = new AsyncQueue<SessionEvent>()
60	  private readonly pending = new Map<string, PendingPermission>()
61	  private readonly mapper = new SdkEventMapper()
62	  private readonly abort = new AbortController()
63	  private readonly query: Query
64	  private readonly pumping: Promise<void>
65	  private engineSessionId: string | undefined
66	
67	  constructor(private readonly options: SdkSessionOptions) {
68	    this.id = options.id
69	    this.profile = options.profile
70	    this.engineSessionId = options.resumeEngineSessionId
71	    this.query = options.query({ prompt: this.input, options: this.buildOptions() })
72	    this.pumping = this.pump()
73	  }
74	
75	  /** Engine-side id, known after `session_started`. Needed to resume after a reload. */
76	  get engineSession(): string | undefined {
77	    return this.engineSessionId
78	  }
79	
80	  send(text: string): void {
81	    this.output.push({ type: 'user_message', text })
82	    this.input.push({
83	      type: 'user',
84	      message: { role: 'user', content: text },
85	      parent_tool_use_id: null,
86	    })
87	  }
88	
89	  events(): AsyncIterable<SessionEvent> {
90	    return this.output
91	  }
92	
93	  respondToPermission(requestId: string, decision: PermissionDecision): void {
94	    const pending = this.pending.get(requestId)
95	    if (!pending) return
96	    this.pending.delete(requestId)
97	    this.output.push({ type: 'permission_resolved', requestId, decision: decision.kind })
98	    pending.resolve(toPermissionResult(decision, pending.input))
99	  }
100	
101	  async interrupt(): Promise<void> {
102	    await this.query.interrupt()
103	  }
104	
105	  async dispose(): Promise<void> {
106	    this.denyAllPending('Session closed')
107	    this.input.end()
108	    this.abort.abort()
109	    this.query.close()
110	    // The engine stream normally completes once the process is gone; the
111	    // timeout covers a process that will not die.
112	    await Promise.race([this.pumping, new Promise((r) => setTimeout(r, 2000))])
113	    this.finish()
114	  }
115	
116	  private buildOptions(): Options {
117	    const { profile } = this.options
118	    const options: Options = {
119	      abortController: this.abort,
120	      cwd: this.options.cwd,
121	      model: profile.model,
122	      permissionMode: 'default',
123	      includePartialMessages: true,
124	      // Project settings so the workspace's .claude/ and CLAUDE.md apply; not
125	      // the user's global settings, which belong to this machine, not the repo.
126	      settingSources: ['project', 'local'],
127	      executable: 'node',
128	      pathToClaudeCodeExecutable: this.options.cliPath,
129	      spawnClaudeCodeProcess: spawnWithRuntime(this.options.runtime, this.options.onStderr ?? (() => {})),
130	      canUseTool: (toolName, input, ctx) => this.requestPermission(toolName, input, ctx),
131	      env: this.options.env ?? {},
132	    }
133	    if (profile.effort) options.effort = profile.effort
134	    if (this.options.resumeEngineSessionId) options.resume = this.options.resumeEngineSessionId
135	    if (this.options.hooks) options.hooks = this.sdkHooks(this.options.hooks)
136	    if (this.options.systemPrompt !== undefined) options.systemPrompt = this.options.systemPrompt
137	    if (this.options.tools) options.tools = this.options.tools
138	    if (this.options.ownTools?.length) {
139	      const ctx = { cwd: this.options.cwd, signal: this.abort.signal, files: new ReadTracker() }
140	      const server = toolServer(this.options.ownTools, ctx)
141	      options.mcpServers = { [server.name]: server }
142	    }
143	    return options
144	  }
145	
146	  /** Maps the engine-agnostic hooks onto the SDK's hook protocol. */
147	  private sdkHooks(hooks: SessionHooks): NonNullable<Options['hooks']> {
148	    const registered: NonNullable<Options['hooks']> = {}
149	    if (hooks.preToolUse) {
150	      const pre = hooks.preToolUse.bind(hooks)
151	      const callback: HookCallback = async (input): Promise<HookJSONOutput> => {
152	        if (input.hook_event_name !== 'PreToolUse') return {}
153	        const outcome = await pre({ toolName: bareToolName(input.tool_name), input: input.tool_input, toolUseId: input.tool_use_id })
154	        if (outcome && 'deny' in outcome) {
155	          return { hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: outcome.deny } }
156	        }
157	        if (!outcome?.allow && !outcome?.additionalContext) return {}
158	        return {
159	          hookSpecificOutput: {
160	            hookEventName: 'PreToolUse',
161	            ...(outcome.allow ? { permissionDecision: 'allow' } : {}),
162	            ...(outcome.additionalContext ? { additionalContext: outcome.additionalContext } : {}),
163	          },
164	        }
165	      }
166	      registered.PreToolUse = [{ hooks: [callback] }]
167	    }
168	    if (hooks.postToolUse) {
169	      const post = hooks.postToolUse.bind(hooks)
170	      const callback: HookCallback = async (input): Promise<HookJSONOutput> => {
171	        if (input.hook_event_name !== 'PostToolUse') return {}
172	        const output = typeof input.tool_response === 'string' ? input.tool_response : JSON.stringify(input.tool_response)
173	        const outcome = await post({
174	          toolName: bareToolName(input.tool_name),
175	          input: input.tool_input,
176	          toolUseId: input.tool_use_id,
177	          output,
178	          isError: false,
179	        })
180	        if (outcome?.additionalContext) {
181	          return { hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: outcome.additionalContext } }
182	        }
183	        return {}
184	      }
185	      registered.PostToolUse = [{ hooks: [callback] }]
186	    }
187	    return registered
188	  }
189	
190	  private requestPermission(
191	    toolName: string,
192	    input: Record<string, unknown>,
193	    ctx: Parameters<NonNullable<Options['canUseTool']>>[2],
194	  ): Promise<PermissionResult> {
195	    return new Promise((resolve) => {
196	      const requestId = ctx.toolUseID
197	      this.pending.set(requestId, { resolve, input })
198	      ctx.signal.addEventListener('abort', () => {
199	        if (this.pending.delete(requestId)) resolve({ behavior: 'deny', message: 'Cancelled' })
200	      })
201	      this.output.push({
202	        type: 'permission_request',
203	        requestId,
204	        toolName: bareToolName(toolName),
205	        input,
206	        ...(ctx.title ? { title: ctx.title } : {}),
207	        ...(ctx.description ? { description: ctx.description } : {}),
208	      })
209	    })
210	  }
211	
212	  private denyAllPending(message: string): void {
213	    for (const [id, pending] of this.pending) {
214	      this.pending.delete(id)
215	      pending.resolve({ behavior: 'deny', message })
216	    }
217	  }
218	
219	  private async pump(): Promise<void> {
220	    try {
221	      for await (const message of this.query) {
222	        this.options.trace?.(describeMessage(message))
223	        for (const event of this.mapper.map(message)) {
224	          if (event.type === 'session_started') this.engineSessionId = event.engineSessionId
225	          this.output.push(event)
226	        }
227	      }
228	    } catch (error) {
229	      if (!this.abort.signal.aborted) {
230	        this.output.push({ type: 'error', message: errorMessage(error), fatal: true })
231	      }
232	    } finally {
233	      this.denyAllPending('Session ended')
234	      this.finish()
235	    }
236	  }
237	
238	  private finish(): void {
239	    if (this.output.isEnded) return
240	    this.output.push({ type: 'ended' })
241	    this.output.end()
242	  }
243	}
244	
245	/**
246	 * The engine validates an allow as `{ updatedInput: record }`, so the
247	 * unchanged input is echoed back; the typings mark it optional but the
248	 * CLI does not.
249	 */
250	function toPermissionResult(decision: PermissionDecision, input: Record<string, unknown>): PermissionResult {
251	  switch (decision.kind) {
252	    case 'allow':
253	      return { behavior: 'allow', updatedInput: input, decisionClassification: 'user_temporary' }
254	    case 'deny':
255	      return { behavior: 'deny', message: decision.message ?? 'Denied by user', decisionClassification: 'user_reject' }
256	  }
257	}
258	
259	function errorMessage(error: unknown): string {
260	  return error instanceof Error ? error.message : String(error)
261	}
262	
263	/** One line per engine message: kind, and for stream events the raw event and delta kinds. */
264	export function describeMessage(msg: SDKMessage): string {
265	  switch (msg.type) {
266	    case 'stream_event': {
267	      const event = msg.event as { type: string; delta?: { type?: string }; content_block?: { type?: string } }
268	      const detail = event.delta?.type ?? event.content_block?.type
269	      return `stream_event ${event.type}${detail ? ` ${detail}` : ''}`
270	    }
271	    case 'system':
272	      return `system ${msg.subtype}${'status' in msg ? ` ${String(msg.status)}` : ''}`
273	    case 'assistant':
274	      return `assistant [${msg.message.content.map((b) => b.type).join(', ')}]`
275	    case 'user': {
276	      const content = msg.message.content
277	      return `user ${typeof content === 'string' ? 'text' : `[${content.map((b) => b.type).join(', ')}]`}`
278	    }
279	    case 'result':
280	      return `result ${msg.subtype} ${msg.duration_ms}ms`
281	    default:
282	      return msg.type
283	  }
284	}
