1	import type { CodeSession, PermissionDecision, SessionEvent, TurnUsage } from '../session/code-session'
2	import type { SessionHooks } from '../session/hooks'
3	import type { ModelProfile } from '../session/model-profile'
4	import { AsyncQueue } from '../session/async-queue'
5	import type { ChatCompletionClient, ChatMessage, ToolCall, Usage } from './chat-messages'
6	import { ReadTracker } from './tools/read-tracker'
7	import { toDefinition, type Tool, type ToolOutput } from './tools/tool'
8	
9	export type OpenAiSessionOptions = {
10	  id: string
11	  profile: ModelProfile
12	  cwd: string
13	  client: ChatCompletionClient
14	  tools: Tool[]
15	  systemPrompt: string
16	  hooks?: SessionHooks
17	  /** Tool rounds per user turn before the engine gives up; a runaway loop costs money. */
18	  maxRoundsPerTurn?: number
19	}
20	
21	/**
22	 * Our own agent loop over an OpenAI-compatible model: stream a completion,
23	 * run the tool calls it asked for, feed results back, repeat until it
24	 * answers without tools. Same events as the Claude engine.
25	 */
26	export class OpenAiSession implements CodeSession {
27	  readonly id: string
28	  readonly profile: ModelProfile
29	  private readonly output = new AsyncQueue<SessionEvent>()
30	  private readonly messages: ChatMessage[]
31	  private readonly queue: string[] = []
32	  private readonly files = new ReadTracker()
33	  private readonly pending = new Map<string, (d: PermissionDecision) => void>()
34	  private readonly definitions
35	  private turnAbort = new AbortController()
36	  private running = false
37	  private disposed = false
38	  private turnCounter = 0
39	
40	  constructor(private readonly options: OpenAiSessionOptions) {
41	    this.id = options.id
42	    this.profile = options.profile
43	    this.messages = [{ role: 'system', content: options.systemPrompt }]
44	    this.definitions = options.tools.map(toDefinition)
45	    this.output.push({ type: 'session_started', engineSessionId: options.id, model: options.profile.model })
46	  }
47	
48	  send(text: string): void {
49	    if (this.disposed) return
50	    this.output.push({ type: 'user_message', text })
51	    this.queue.push(text)
52	    if (!this.running) void this.drain()
53	  }
54	
55	  events(): AsyncIterable<SessionEvent> {
56	    return this.output
57	  }
58	
59	  respondToPermission(requestId: string, decision: PermissionDecision): void {
60	    const resolve = this.pending.get(requestId)
61	    if (!resolve) return
62	    this.pending.delete(requestId)
63	    this.output.push({ type: 'permission_resolved', requestId, decision: decision.kind })
64	    resolve(decision)
65	  }
66	
67	  async interrupt(): Promise<void> {
68	    this.turnAbort.abort()
69	    for (const [id, resolve] of this.pending) {
70	      this.pending.delete(id)
71	      resolve({ kind: 'deny', message: 'Interrupted' })
72	    }
73	  }
74	
75	  async dispose(): Promise<void> {
76	    if (this.disposed) return
77	    this.disposed = true
78	    await this.interrupt()
79	    this.output.push({ type: 'ended' })
80	    this.output.end()
81	  }
82	
83	  private async drain(): Promise<void> {
84	    this.running = true
85	    try {
86	      while (this.queue.length > 0 && !this.disposed) {
87	        const text = this.queue.shift()!
88	        this.messages.push({ role: 'user', content: text })
89	        await this.runTurn()
90	      }
91	    } finally {
92	      this.running = false
93	    }
94	  }
95	
96	  private async runTurn(): Promise<void> {
97	    this.turnAbort = new AbortController()
98	    const signal = this.turnAbort.signal
99	    const turn = ++this.turnCounter
100	    const usage: TurnUsage = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 }
101	    const started = Date.now()
102	    const maxRounds = this.options.maxRoundsPerTurn ?? 50
103	    try {
104	      for (let round = 1; ; round++) {
105	        if (round > maxRounds) {
106	          this.emitError(`Stopped after ${maxRounds} tool rounds in one turn`)
107	          return this.finishTurn(usage, started, true, ['max tool rounds'])
108	        }
109	        this.output.push({ type: 'status', status: 'requesting' })
110	        const assistant = await this.complete(`${turn}.${round}`, signal, usage)
111	        this.messages.push(assistant)
112	        if (assistant.toolCalls.length === 0) return this.finishTurn(usage, started, false, [])
113	        for (const call of assistant.toolCalls) {
114	          if (signal.aborted) throw new InterruptedError()
115	          const result = await this.runTool(call, signal)
116	          this.output.push({ type: 'tool_result', toolUseId: call.id, text: result.text, isError: result.isError })
117	          this.messages.push({ role: 'tool', toolCallId: call.id, content: result.text })
118	        }
119	        if (signal.aborted) throw new InterruptedError()
120	      }
121	    } catch (error) {
122	      this.repairAfterAbort()
123	      if (error instanceof InterruptedError || signal.aborted) {
124	        return this.finishTurn(usage, started, true, ['interrupted'])
125	      }
126	      const message = error instanceof Error ? error.message : String(error)
127	      this.emitError(message)
128	      return this.finishTurn(usage, started, true, [message])
129	    }
130	  }
131	
132	  /** Streams one completion, emitting deltas, and returns the assembled assistant message. */
133	  private async complete(
134	    messageId: string,
135	    signal: AbortSignal,
136	    usage: TurnUsage,
137	  ): Promise<Extract<ChatMessage, { role: 'assistant' }>> {
138	    let text = ''
139	    let reasoning = ''
140	    const calls = new Map<number, ToolCall>()
141	    for await (const delta of this.options.client.stream({
142	      model: this.options.profile.model,
143	      messages: this.messages,
144	      tools: this.definitions,
145	      signal,
146	    })) {
147	      switch (delta.type) {
148	        case 'text':
149	          text += delta.text
150	          this.output.push({ type: 'assistant_text', messageId, delta: delta.text })
151	          break
152	        case 'reasoning':
153	          reasoning += delta.text
154	          this.output.push({ type: 'assistant_thinking', messageId, delta: delta.text })
155	          break
156	        case 'tool_call_start':
157	          calls.set(delta.index, { id: delta.id, name: delta.name, arguments: '' })
158	          break
159	        case 'tool_call_arguments': {
160	          const call = calls.get(delta.index)
161	          if (call) call.arguments += delta.text
162	          break
163	        }
164	        case 'done':
165	          if (delta.usage) addUsage(usage, delta.usage)
166	          break
167	      }
168	    }
169	    if (text) this.output.push({ type: 'assistant_message', messageId, text })
170	    const toolCalls = [...calls.entries()].sort((a, b) => a[0] - b[0]).map(([, c]) => c)
171	    for (const call of toolCalls) {
172	      this.output.push({
173	        type: 'tool_call',
174	        toolUseId: call.id,
175	        name: call.name,
176	        input: parseArguments(call.arguments) ?? call.arguments,
177	      })
178	    }
179	    return { role: 'assistant', content: text, ...(reasoning ? { reasoning } : {}), toolCalls }
180	  }
181	
182	  private async runTool(call: ToolCall, signal: AbortSignal): Promise<ToolOutput> {
183	    const tool = this.options.tools.find((t) => t.name === call.name)
184	    if (!tool) return { text: `Unknown tool: ${call.name}`, isError: true }
185	    const raw = parseArguments(call.arguments)
186	    if (raw === undefined) return { text: `Tool arguments are not valid JSON: ${call.arguments.slice(0, 200)}`, isError: true }
187	    const parsed = tool.schema.safeParse(raw)
188	    if (!parsed.success) {
189	      const issues = parsed.error.issues.map((i) => `${i.path.join('.') || '(root)'}: ${i.message}`).join('; ')
190	      return { text: `Invalid arguments for ${tool.name}: ${issues}`, isError: true }
191	    }
192	    const use = { toolName: tool.name, input: parsed.data, toolUseId: call.id }
193	    const pre = await this.options.hooks?.preToolUse?.(use)
194	    if (pre && 'deny' in pre) return { text: `Blocked: ${pre.deny}`, isError: true }
195	    if (!tool.readOnly && !pre?.allow) {
196	      const decision = await this.askPermission(call.id, tool.name, parsed.data, signal)
197	      if (decision.kind === 'deny') return { text: `Denied by user${decision.message ? `: ${decision.message}` : ''}`, isError: true }
198	    }
199	    let output: ToolOutput
200	    try {
201	      output = await tool.execute(parsed.data, { cwd: this.options.cwd, signal, files: this.files })
202	    } catch (error) {
203	      output = { text: `${tool.name} failed: ${error instanceof Error ? error.message : String(error)}`, isError: true }
204	    }
205	    const post = await this.options.hooks?.postToolUse?.({ ...use, output: output.text, isError: output.isError })
206	    const context = [pre?.additionalContext, post?.additionalContext].filter((c): c is string => !!c)
207	    return context.length ? { ...output, text: `${output.text}\n\n${context.join('\n\n')}` } : output
208	  }
209	
210	  private askPermission(requestId: string, toolName: string, input: unknown, signal: AbortSignal): Promise<PermissionDecision> {
211	    return new Promise((resolve) => {
212	      this.pending.set(requestId, resolve)
213	      signal.addEventListener('abort', () => {
214	        if (this.pending.delete(requestId)) resolve({ kind: 'deny', message: 'Interrupted' })
215	      })
216	      this.output.push({ type: 'permission_request', requestId, toolName, input })
217	    })
218	  }
219	
220	  /**
221	   * An assistant message with tool calls must be answered before the next
222	   * user message, or the API rejects the history. After an abort, whatever
223	   * calls are still unanswered get a synthetic result.
224	   */
225	  private repairAfterAbort(): void {
226	    const last = this.messages[this.messages.length - 1]
227	    if (!last || last.role !== 'assistant') return
228	    const answered = new Set<string>()
229	    for (let i = this.messages.length - 1; i >= 0; i--) {
230	      const m = this.messages[i]!
231	      if (m.role === 'tool') answered.add(m.toolCallId)
232	      else break
233	    }
234	    for (const call of last.toolCalls) {
235	      if (!answered.has(call.id)) this.messages.push({ role: 'tool', toolCallId: call.id, content: '[interrupted before this tool ran]' })
236	    }
237	  }
238	
239	  private finishTurn(usage: TurnUsage, started: number, isError: boolean, errors: string[]): void {
240	    this.output.push({ type: 'status', status: 'idle' })
241	    this.output.push({ type: 'turn_done', usage, durationMs: Date.now() - started, isError, errors })
242	  }
243	
244	  private emitError(message: string): void {
245	    this.output.push({ type: 'error', message, fatal: false })
246	  }
247	}
248	
249	class InterruptedError extends Error {
250	  constructor() {
251	    super('interrupted')
252	  }
253	}
254	
255	function addUsage(total: TurnUsage, usage: Usage): void {
256	  total.inputTokens += usage.promptTokens - usage.cachedTokens
257	  total.cacheReadTokens += usage.cachedTokens
258	  total.outputTokens += usage.completionTokens
259	}
260	
261	function parseArguments(text: string): unknown {
262	  if (text.trim() === '') return {}
263	  try {
264	    return JSON.parse(text)
265	  } catch {
266	    return undefined
267	  }
268	}
