2	import { join } from 'node:path'
3	import type { SessionEvent } from '../session/code-session'
4	
5	export type RunLogEntry = { at: string; event: SessionEvent }
6	
7	/**
8	 * Append-only JSONL of every event a session produced, one file per session
9	 * under `.agent/runs/<session id>/events.jsonl`. The transcript view is
10	 * rebuilt from it after a reload, and later phases read it for observability.
11	 *
12	 * Writes are chained so entries land in emission order even when the caller
13	 * does not await.
14	 */
15	export class RunLog {
16	  private chain: Promise<void> = Promise.resolve()
17	
18	  /** The session's run directory; what belongs to this run and not to the workspace lives here. */
19	  constructor(readonly dir: string) {}
20	
21	  static forSession(workspaceRoot: string, sessionId: string): RunLog {
22	    return new RunLog(join(workspaceRoot, '.agent', 'runs', sessionId))
23	  }
24	
25	  get path(): string {
26	    return join(this.dir, 'events.jsonl')
27	  }
28	
29	  append(event: SessionEvent): Promise<void> {
30	    const entry: RunLogEntry = { at: new Date().toISOString(), event }
31	    this.chain = this.chain.then(async () => {
32	      await mkdir(this.dir, { recursive: true })
33	      await appendFile(this.path, JSON.stringify(entry) + '\n', 'utf8')
34	    })
35	    return this.chain
36	  }
37	
38	  async read(): Promise<RunLogEntry[]> {
39	    let text: string
40	    try {
41	      text = await readFile(this.path, 'utf8')
42	    } catch (error) {
43	      if (isMissingFile(error)) return []
44	      throw error
45	    }
46	    return text
47	      .split('\n')
48	      .filter((line) => line.length > 0)
49	      .map((line) => JSON.parse(line) as RunLogEntry)
50	  }
51	}
52	
53	function isMissingFile(error: unknown): boolean {
54	  return typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT'
55	}
