1	import type { SDKMessage } from '@anthropic-ai/claude-agent-sdk'
2	import type { SessionEvent, TurnUsage } from '../session/code-session'
3	import { bareToolName } from './tool-server'
4	
5	/**
6	 * Turns the Agent SDK's message stream into SessionEvents.
7	 *
8	 * Stateful because streaming deltas do not carry the message id they belong
9	 * to; `message_start` does, and the mapper remembers it until the next one.
10	 *
11	 * User messages are not mapped: the session emits `user_message` when it
12	 * sends, and replays on resume are restored from the run log instead.
13	 */
14	export class SdkEventMapper {
15	  private currentMessageId = ''
16	
17	  map(msg: SDKMessage): SessionEvent[] {
18	    switch (msg.type) {
19	      case 'system':
20	        return this.mapSystem(msg)
21	      case 'stream_event':
22	        return this.mapStreamEvent(msg)
23	      case 'assistant':
24	        return this.mapAssistant(msg)
25	      case 'user':
26	        return this.mapUser(msg)
27	      case 'result':
28	        return this.mapResult(msg)
29	      case 'auth_status':
30	        return msg.error ? [{ type: 'error', message: `Authentication: ${msg.error}`, fatal: false }] : []
31	      default:
32	        return []
33	    }
34	  }
35	
36	  private mapSystem(msg: Extract<SDKMessage, { type: 'system' }>): SessionEvent[] {
37	    switch (msg.subtype) {
38	      case 'init':
39	        return [
40	          {
41	            type: 'session_started',
42	            engineSessionId: msg.session_id,
43	            model: msg.model,
44	            engineVersion: msg.claude_code_version,
45	          },
46	        ]
47	      case 'status':
48	        return [{ type: 'status', status: msg.status ?? 'idle' }]
49	      case 'compact_boundary':
50	        return [{ type: 'status', status: 'idle' }]
51	      default:
52	        return []
53	    }
54	  }
55	
56	  private mapStreamEvent(msg: Extract<SDKMessage, { type: 'stream_event' }>): SessionEvent[] {
57	    const event = msg.event
58	    const parent = parentOf(msg.parent_tool_use_id)
59	    if (event.type === 'message_start') {
60	      this.currentMessageId = event.message.id
61	      return []
62	    }
63	    if (event.type !== 'content_block_delta') return []
64	    const messageId = this.currentMessageId
65	    if (event.delta.type === 'text_delta') {
66	      return [{ type: 'assistant_text', messageId, delta: event.delta.text, ...parent }]
67	    }
68	    if (event.delta.type === 'thinking_delta') {
69	      return [{ type: 'assistant_thinking', messageId, delta: event.delta.thinking, ...parent }]
70	    }
71	    return []
72	  }
73	
74	  private mapAssistant(msg: Extract<SDKMessage, { type: 'assistant' }>): SessionEvent[] {
75	    const parent = parentOf(msg.parent_tool_use_id)
76	    const events: SessionEvent[] = []
77	    if (msg.error) {
78	      events.push({ type: 'error', message: `Assistant error: ${msg.error}`, fatal: false })
79	    }
80	    const textParts: string[] = []
81	    for (const block of msg.message.content) {
82	      if (block.type === 'text') {
83	        textParts.push(block.text)
84	      } else if (block.type === 'tool_use') {
85	        events.push({ type: 'tool_call', toolUseId: block.id, name: bareToolName(block.name), input: block.input, ...parent })
86	      }
87	    }
88	    if (textParts.length > 0) {
89	      events.push({ type: 'assistant_message', messageId: msg.message.id, text: textParts.join(''), ...parent })
90	    }
91	    return events
92	  }
93	
94	  private mapUser(msg: Extract<SDKMessage, { type: 'user' }>): SessionEvent[] {
95	    if ('isReplay' in msg && msg.isReplay) return []
96	    const content = msg.message.content
97	    if (typeof content === 'string') return []
98	    const parent = parentOf(msg.parent_tool_use_id)
99	    const events: SessionEvent[] = []
100	    for (const block of content) {
101	      if (block.type !== 'tool_result') continue
102	      events.push({
103	        type: 'tool_result',
104	        toolUseId: block.tool_use_id,
105	        text: toolResultText(block.content),
106	        isError: block.is_error === true,
107	        ...parent,
108	      })
109	    }
110	    return events
111	  }
112	
113	  private mapResult(msg: Extract<SDKMessage, { type: 'result' }>): SessionEvent[] {
114	    const usage: TurnUsage = {
115	      inputTokens: msg.usage.input_tokens,
116	      outputTokens: msg.usage.output_tokens,
117	      cacheReadTokens: msg.usage.cache_read_input_tokens,
118	      cacheWriteTokens: msg.usage.cache_creation_input_tokens,
119	      costUsd: msg.total_cost_usd,
120	    }
121	    const errors = msg.subtype === 'success' ? [] : msg.errors
122	    if (msg.subtype !== 'success' && errors.length === 0) errors.push(msg.subtype)
123	    return [{ type: 'turn_done', usage, durationMs: msg.duration_ms, isError: msg.is_error, errors }]
124	  }
125	}
126	
127	function parentOf(parentToolUseId: string | null): { parentToolUseId?: string } {
128	  return parentToolUseId ? { parentToolUseId } : {}
129	}
130	
131	function toolResultText(content: unknown): string {
132	  if (content === undefined || content === null) return ''
133	  if (typeof content === 'string') return content
134	  if (Array.isArray(content)) {
135	    return content
136	      .map((part: unknown) => {
137	        if (typeof part === 'object' && part !== null && 'type' in part && part.type === 'text' && 'text' in part) {
138	          return String(part.text)
139	        }
140	        return `[${typeof part === 'object' && part !== null && 'type' in part ? String(part.type) : 'content'}]`
141	      })
142	      .join('\n')
143	  }
144	  return JSON.stringify(content)
145	}
