1	import { isAbsolute, matchesGlob, relative, resolve } from 'node:path'
2	import type { PreToolUseOutcome, SessionHooks, ToolUse } from '../session/hooks'
3	import { isReadOnlyCommand, isReadOnlySegment, type ReadOnlyContext } from './read-only-commands'
4	import { bashPatternMatches, parseRule, type PermissionRule } from './permission-rules'
5	import { splitShellCommand, type ShellSegment } from './shell-split'
6	
7	export type PermissionRules = { allow: string[]; deny: string[] }
8	
9	/** Tools that only look; their calls never prompt unless a deny rule names them. */
10	const READ_ONLY_TOOLS = new Set(['Read', 'Glob', 'Grep', 'JsonSchema', 'JsonQuery', 'LS', 'NotebookRead', 'TodoRead', 'TodoWrite'])
11	
12	const FILE_TOOLS = new Set(['Read', 'Write', 'Edit', 'MultiEdit', 'NotebookEdit', 'NotebookRead', 'Glob', 'Grep', 'JsonSchema', 'JsonQuery', 'LS'])
13	
14	/**
15	 * Decides tool calls before any permission prompt, on every engine: a deny
16	 * rule blocks, a read-only call or one covered by the project's allow rules
17	 * goes through, everything else is asked. Rules are read on each call so a
18	 * rule written by "Allow for project" applies to the next call.
19	 */
20	export class PermissionPolicy implements SessionHooks {
21	  private readonly readOnlyContext: ReadOnlyContext
22	
23	  constructor(
24	    private readonly cwd: string,
25	    private readonly rules: () => PermissionRules,
26	  ) {
27	    this.readOnlyContext = { insideProject: (path) => !this.relativeTo(path).startsWith('..') }
28	  }
29	
30	  async preToolUse(tool: ToolUse): Promise<PreToolUseOutcome> {
31	    const { allow, deny } = this.rules()
32	    const denied = deny.find((rule) => this.matches(parseRule(rule), tool, 'any'))
33	    if (denied) return { deny: `Blocked by the project's permission rule ${denied} (kiwiAgent.permissions.deny).` }
34	    if (this.isReadOnly(tool)) return { allow: true }
35	    if (allow.some((rule) => this.matches(parseRule(rule), tool, 'all'))) return { allow: true }
36	    return undefined
37	  }
38	
39	  private isReadOnly(tool: ToolUse): boolean {
40	    if (READ_ONLY_TOOLS.has(tool.toolName)) return true
41	    return tool.toolName === 'Bash' && isReadOnlyCommand(this.command(tool), this.readOnlyContext)
42	  }
43	
44	  /**
45	   * For Bash, `all` requires the rule to cover every segment (an allow), while
46	   * `any` fires on one (a deny). A substitution hides a command, so no allow
47	   * rule can cover it.
48	   */
49	  private matches(rule: PermissionRule, tool: ToolUse, segments: 'all' | 'any'): boolean {
50	    if (rule.tool !== tool.toolName) return false
51	    if (rule.pattern === undefined) return tool.toolName !== 'Bash' || segments === 'any' || !splitShellCommand(this.command(tool)).substitutes
52	    if (tool.toolName === 'Bash') {
53	      const parsed = splitShellCommand(this.command(tool))
54	      if (segments === 'all' && parsed.substitutes) return false
55	      const covered = (s: ShellSegment) => bashPatternMatches(rule.pattern!, s.tokens) || (segments === 'all' && isReadOnlySegment(s, this.readOnlyContext))
56	      return segments === 'all' ? parsed.segments.every(covered) : parsed.segments.some(covered)
57	    }
58	    if (FILE_TOOLS.has(tool.toolName)) {
59	      const path = this.relativePath(tool)
60	      return path !== undefined && matchesGlob(path, rule.pattern)
61	    }
62	    return false
63	  }
64	
65	  private command(tool: ToolUse): string {
66	    const command = (tool.input as { command?: unknown })?.command
67	    return typeof command === 'string' ? command : ''
68	  }
69	
70	  private relativePath(tool: ToolUse): string | undefined {
71	    const input = (tool.input ?? {}) as Record<string, unknown>
72	    const raw = input['file_path'] ?? input['notebook_path'] ?? input['path']
73	    return typeof raw === 'string' ? this.relativeTo(raw) : undefined
74	  }
75	
76	  private relativeTo(raw: string): string {
77	    const absolute = isAbsolute(raw) ? raw : resolve(this.cwd, raw)
78	    return relative(this.cwd, absolute).split('\\').join('/')
79	  }
80	}
